#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
const int sensorPin = A5;

void setup() {
  Serial.begin(115200);
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Hello, ArduSim!");
  lcd.setCursor(0, 1);
  lcd.print("LCD I2C : 0x27");
}

void loop() {
  int sensorValue = analogRead(sensorPin);
  
  float temperatureCelsius = (sensorValue * 500.0) / 1023.0;
  float temperatureFahrenheit = (temperatureCelsius * 1.8) + 32.0;

  Serial.print("Temperature: ");
  Serial.print(temperatureCelsius);
  Serial.print(" °C  |  ");
  Serial.print(temperatureFahrenheit);
  Serial.println(" °F");
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Temperature: ");
  lcd.setCursor(0, 1);
  lcd.print(temperatureCelsius);
  lcd.print("°C ");
  lcd.print(temperatureFahrenheit);
  lcd.print("°F");
  delay(1000);
}
